mapper.select:
/* InptResultAnalyMapper.selectSugiList */
SELECT T1.INPT_MST_SRNO AS INPT_MST_SRNO, -- INPT_MST_SRNO 마스터번호 T1.ACTL_FX_REFNO AS ACTL_FX_REFNO, -- ACTL_FX_REFNO ref번호 T1.FX_REFNO_SRNO AS FX_REFNO_SRNO, -- FX_REFNO_SRNO 회차 T2.INPT_BL_GRP_NO AS INPT_BL_GRP_NO, -- INPT_BL_GRP_NO BL그룹 ( SELECT AI_INPT_CMN_CD_ENG_NM FROM CSPD112TI WHERE AI_INPT_GRP_CD = DECODE(T1.INPT_ATMC_BIZ_DSCD, '1', '240', '230') AND AI_INPT_CMN_CD = TO_CHAR(T3.INPT_SANCTION_NO) ) AS ITM_NM, -- ITM_NM 항목명 CASE WHEN DECODE(ITM_INPT_RVSN_YN, 'U', NULL, INPT_SANCTION_DAT_TXT) IS NULL THEN '미추출' ELSE T3.INPT_SANCTION_DAT_TXT END AS EXT_VAL, -- EXT_VAL 추출값 NVL(T3.ITM_INPT_HNDG_INP_DAT_TXT,' ') AS SUGI_VAL, -- SUGI_VAL 수기값 CASE WHEN DECODE(ITM_INPT_RVSN_YN, 'U', NULL, INPT_SANCTION_DAT_TXT) = ITM_INPT_HNDG_INP_DAT_TXT THEN '오수정(동일)' WHEN ITM_INPT_HNDG_INP_DAT_TXT = '.' OR ITM_INPT_HNDG_INP_DAT_TXT = '-' THEN '과탐' WHEN DECODE(ITM_INPT_RVSN_YN, 'U', NULL, INPT_SANCTION_DAT_TXT) IS NULL THEN '미추출' WHEN DECODE(ITM_INPT_RVSN_YN, 'U', NULL, INPT_SANCTION_DAT_TXT) = '++' AND ITM_INPT_HNDG_INP_DAT_TXT IS NOT NULL THEN '오수정(++)' ELSE '오답' END AS CONF_NM, -- CONF_NM 확인
NVL(CASE WHEN AFRS_TA_EXTC_TXT IS NOT NULL THEN AFRS_TA_EXTC_TXT ELSE BFRS_TA_EXTC_TXT END,'미추출') AS EXT_TA, -- EXT_TA TA추출 NVL(CASE WHEN AFRS_AICR_EXTC_TXT IS NOT NULL THEN AFRS_AICR_EXTC_TXT ELSE BFRS_AICR_EXTC_TXT END,'미추출') AS EXT_AICR, -- EXT_AICR AICR추출 T1.AI_INSPE_ENO AS AI_INSPE_ENO, -- AI_INSPE_ENO 심사자 T3.LST_DB_CHG_DTM AS LST_DB_CHG_DTM, -- LST_DB_CHG_DTM 변경시간 CASE WHEN T1.AI_INPT_ACVT_CD = '140' THEN 'BLOCK' WHEN T1.AI_INPT_ACVT_CD = '160' THEN '승인' END AS AI_INPT_ACVT_CD -- AI_INPT_ACVT_CD 상태 FROM CSPD001TM T1, CSPD002TG T2, CSPD004TF T3 WHERE T1.INPT_RCP_DT = #{schSdate} AND T2.INPT_MST_SRNO = T1.INPT_MST_SRNO AND T3.INPT_MST_SRNO = T2.INPT_MST_SRNO AND T3.INPT_TASK_ID = T2.INPT_TASK_ID AND T3.SAFEWATCH_ITM_YN = 'Y' AND T1.AI_INPT_ACVT_CD IN ('140','160') AND T3.ITM_INPT_HNDG_INP_DAT_TXT IS NOT NULL ORDER BY T1.LST_DB_CHG_DTM, T1.INPT_MST_SRNO, T2.INPT_BL_GRP_NO, T3.INPT_SANCTION_NO
